"""TASK-013 / REQ-024: report completed split evidence without inference."""
import json
from pathlib import Path
from masklab.portable import public_redacted_archive
folder=Path('artifacts/mixed-study')
check=json.loads((folder/'split-ledger-independent.json').read_text());assert check['status']=='PASS'
lines=['# Mixed-question study results','','TASK-007/009/013; REQ-004/005/009/014–020/024. Operator approved all 150 question rows and sequential development/evaluation execution. Both runs use live provider measurements, not simulated evidence.','','## Results','','| Split | Questions | Requests | Correct | Incorrect | Invalid | Finalized correctness | Valid-only accuracy | Estimated USD |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
links=[]
for split,n in [('development',60),('evaluation',90)]:
 a=json.loads((folder/(split+'-analysis.json')).read_text());r=json.loads((folder/(split+'-run.json')).read_text());i=json.loads((folder/(split+'-independent.json')).read_text());c=a['summary']['counts']
 lines.append(f"| {split} | {n} | {c['scheduled']} | {c['correct']} | {c['incorrect']} | {c['invalid']} | {c['correct']/c['finalized']:.2%} | {c['correct']/c['valid']:.2%} | {i['estimated_cost_usd']} |")
 links.append(f"- [{split.title()} results](http://127.0.0.1:8001/#view=results&study={r['study_id']}&run={r['id']}) — run `{r['id']}`.")
 raw=(folder/(split+'.zip')).read_bytes();Path('public-evidence',split+'-redacted.zip').write_bytes(public_redacted_archive(raw))
lines+=['','Failure, refusal, uncertainty and pending counts remain explicit in each archive. Invalid and incorrect outcomes remain in the original evidence.','','## Methods and limitations','','The development decision retained prompts, answer keys, role/frame instructions, output limits, temperature, scoring and analysis unchanged. The decision was persisted before evaluation execution. Development found choice text instead of choice labels, currency-formatted numeric responses and malformed answer objects; those remain invalid under the frozen strict scorer. No retry, rescoring or removal was used to improve outcomes.','','The actual 60/90 question ID sets are disjoint. Both splits use three roles, three belief frames and three repetitions per question. Generated template families overlap splits, and public benchmark training exposure is unknown. CMU source articles do not cross splits. This is a mixed convenience study, not a representative benchmark, training run or population-wide model assessment. Paired intervals use the existing question-cluster bootstrap; exploratory multiple comparisons do not establish rankings or internal mechanisms. Report development and evaluation separately.','','## Usage and integrity','',f"Additional requests: {check['attempts']}; input tokens: {check['input_tokens']}; completion tokens: {check['output_tokens']}; reasoning-token subset: {check['reasoning_tokens_subset']}. Additional estimated cost: USD{check['additional_estimated_cost_usd']}. Cumulative estimated cost including prior verification: USD{check['cumulative_estimated_cost_usd']}; remaining grant: USD{check['remaining_usd']}. Costs use reviewed input/output prices; this is not invoice reconciliation. No automatic top-ups or budget increase.",'','Independent checks verified archive hashes, scores/denominators, paired metrics, usage/costs, split separation, unchanged protocol settings and exactly one attempt per scheduled request. Private original ZIPs and the spending ledger remain outside Git. `public-evidence/` contains explicitly labeled public derivatives; pre-5 p.m. timestamps on the operator-selected day are redacted in textual and numeric provider forms. Private originals remain intact; public derivatives are inspection-only and not standard-import-compatible. Nothing was published, deployed, pushed or submitted.','','## Review in the app','',*links,'','Open each results page, compare the four chart panels, inspect incorrect and invalid responses, and use **Download ZIP** for the original owner evidence. Public copies are in `public-evidence/`. Source/license and sampling details: [QUESTION_STUDY.md](QUESTION_STUDY.md). Current operator approval is recorded separately; immutable imported dataset notes retain their historical draft wording.','']
Path('docs/MIXED_STUDY_RESULTS.md').write_text('\n'.join(lines))
print('Completed report and separate public split archives prepared; no inference or publication')
